(5918285, 861876, 104009, '<td valign="top">ironic just had some of this last weekend.  great setup and shot love even the border. my first 9</td>', 'ironic just had some of this last weekend.  great setup and shot love even the border. my first 9', '2010-03-26 13:16:06.000000', NULL, 1),
(5918286, 862216, 47974, '<td valign="top">Really like the background.  The bright light in the bottom of the cup is distracting but I love all the other lights/reflections in the class.  Also, the glass is not level.</td>', 'Really like the background.  The bright light in the bottom of the cup is distracting but I love all the other lights/reflections in the class.  Also, the glass is not level.', '2010-03-26 13:16:26.000000', NULL, 1),
(5918287, 862210, 47974, '<td valign="top">Nice idea but is just not that appealing of photograph to me.</td>', 'Nice idea but is just not that appealing of photograph to me.', '2010-03-26 13:16:55.000000', NULL, 1),
(5918289, 862034, 47974, '<td valign="top">While it is a very creative photograph and I do understand what you are trying to accomplish it just don''t do it for me.  Had to look at the title to tell what the product is and don''t understand how a range of colors is a product over they type of paint.</td>', 'While it is a very creative photograph and I do understand what you are trying to accomplish it just don''t do it for me.  Had to look at the title to tell what the product is and don''t understand how a range of colors is a product over they type of paint.', '2010-03-26 13:18:50.000000', NULL, 1),
(5918290, 862154, 47974, '<td valign="top">Nicely done and I really like the bit of reflection of the cream on the bottle</td>', 'Nicely done and I really like the bit of reflection of the cream on the bottle', '2010-03-26 13:19:33.000000', NULL, 1),
(5918293, 862048, 47974, '<td valign="top">A little bit shallower DOF would have made the photograph a lot better.  Gives the impression of being out of focus and not really drawing your attention to the Verragio line.</td>', 'A little bit shallower DOF would have made the photograph a lot better.  Gives the impression of being out of focus and not really drawing your attention to the Verragio line.', '2010-03-26 13:21:19.000000', NULL, 1),
(5918294, 862037, 47974, '<td valign="top">Looks more like a snapshot of a bottle in the river.</td>', 'Looks more like a snapshot of a bottle in the river.', '2010-03-26 13:21:54.000000', NULL, 1),
