(5918316, 861523, 47974, '<td valign="top">Very nice photograph and I like the background but would have been better if it was that blue all the way across.</td>', 'Very nice photograph and I like the background but would have been better if it was that blue all the way across.', '2010-03-26 13:40:19.000000', NULL, 1),
(5918318, 861943, 115307, '<td valign="top">This is my favorite picture in this challenge. I hope it does really well.<br/>The shadow and the feather make this "product" very interesting and set its apart from your competitors without turning it into a commercial like some of the images in this challenge</td>', 'This is my favorite picture in this challenge. I hope it does really well.The shadow and the feather make this "product" very interesting and set its apart from your competitors without turning it into a commercial like some of the images in this challenge', '2010-03-26 13:41:04.000000', NULL, 1),
