(5919849, 862160, 96751, '<td valign="top">Magazine ad for sure!</td>', 'Magazine ad for sure!', '2010-03-28 16:10:44.000000', NULL, 1),
(5919850, 862204, 96751, '<td valign="top">I love this shot.  Awesome colors and lighting.  I think it''s a bit too artistic for a true "product shot" but it''s wonderful.</td>', 'I love this shot.  Awesome colors and lighting.  I think it''s a bit too artistic for a true "product shot" but it''s wonderful.', '2010-03-28 16:11:28.000000', NULL, 1),
(5919851, 862112, 96751, '<td valign="top">The box and the ring are fabulous, but whatever the ring is sitting on is way too interesting, and I find myself looking at it far more, trying to figure out what it is.</td>', 'The box and the ring are fabulous, but whatever the ring is sitting on is way too interesting, and I find myself looking at it far more, trying to figure out what it is.', '2010-03-28 16:12:20.000000', NULL, 1),
(5919862, 861874, 99708, '<td valign="top">For me the picture needed more lighting, it appears dull.</td>', 'For me the picture needed more lighting, it appears dull.', '2010-03-28 16:25:54.000000', NULL, 1),
(5919865, 861966, 99708, '<td valign="top">The picture is beautiful, and the concept is great.  I love how Tiffany is clearly seen (with the exception of the one bubble).  Just wish the ring sparkled more from under the water.  Other than the ring comment, I truly enjoy this shot.  Good job.</td>', 'The picture is beautiful, and the concept is great.  I love how Tiffany is clearly seen (with the exception of the one bubble).  Just wish the ring sparkled more from under the water.  Other than the ring comment, I truly enjoy this shot.  Good job.', '2010-03-28 16:27:35.000000', NULL, 1),
(5919866, 862152, 99708, '<td valign="top">If it weren''t for the title, I wouldn''t know this was maple syrup.  I was thinking, jam, some sort of orange drink - wasn''t sure.  The coloring is beautiful, and the shape of the bottle is interesting.</td>', 'If it weren''t for the title, I wouldn''t know this was maple syrup.  I was thinking, jam, some sort of orange drink - wasn''t sure.  The coloring is beautiful, and the shape of the bottle is interesting.', '2010-03-28 16:28:46.000000', NULL, 1),
(5919867, 860959, 99708, '<td valign="top">Looks refreshing (glad you went with the can instead of the bottle - easier to see), and the surroundings also give it a relaxing appeal.  Nice.</td>', 'Looks refreshing (glad you went with the can instead of the bottle - easier to see), and the surroundings also give it a relaxing appeal.  Nice.', '2010-03-28 16:29:50.000000', NULL, 1),
(5919868, 862112, 99708, '<td valign="top">Love the contrast between the jewlery and the black stone.  Nice placement of the designer logo.  And I really like the way the top stones/water seem to curve alog the back edge of the bracelet (?).  One of my favorites so far.</td>', 'Love the contrast between the jewlery and the black stone.  Nice placement of the designer logo.  And I really like the way the top stones/water seem to curve alog the back edge of the bracelet (?).  One of my favorites so far.', '2010-03-28 16:31:22.000000', NULL, 1),
(5919871, 861397, 99708, '<td valign="top">I came back to this one for a second look.  Maybe it''s just my eyes, but it all seems to be just slightly oof.</td>', 'I came back to this one for a second look.  Maybe it''s just my eyes, but it all seems to be just slightly oof.', '2010-03-28 16:32:44.000000', NULL, 1),
(5919874, 862207, 99708, '<td valign="top">This is beautiful.  The colors of te car, and the softness of the background work well together.  I would have liked it better if the "head lights" weren''t at the other end of the pic, I find them a tad distracting - but that is just my humbled opinion.   But you are still getting a high score from me.  :)</td>', 'This is beautiful.  The colors of te car, and the softness of the background work well together.  I would have liked it better if the "head lights" weren''t at the other end of the pic, I find them a tad distracting - but that is just my humbled opinion.   But you are still getting a high score from me.  :)', '2010-03-28 16:34:36.000000', NULL, 1),
(5919876, 862122, 99708, '<td valign="top">Liking the subject for this one, Yankee Candles are in every room of my house.  Lets start with the positives:  Nice close up of the candle, you can pretty much read every detail in the label.  Negatives: The bg is distracting to me. May have worked with a light green to correlate with the label and bring out the coloring in the candle.</td>', 'Liking the subject for this one, Yankee Candles are in every room of my house.  Lets start with the positives:  Nice close up of the candle, you can pretty much read every detail in the label.  Negatives: The bg is distracting to me. May have worked with a light green to correlate with the label and bring out the coloring in the candle.', '2010-03-28 16:37:15.000000', NULL, 1),
