(5927557, 861755, 28742, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lutchenko:</b></div><hr/><i> Ok I sat through the whole of that Dan Akroyd vid.....  </i></td></tr></table> <br/>LOL - Me too! "crystal head triple herkamer diamond filtered newfoundland deep aquafer pure spirit vodka." WOW<br/>Congratulations on the RIBBON, Karen! Great shot!</td>', 'Originally posted by Lutchenko: Ok I sat through the whole of that Dan Akroyd vid.....   LOL - Me too! "crystal head triple herkamer diamond filtered newfoundland deep aquafer pure spirit vodka." WOWCongratulations on the RIBBON, Karen! Great shot!', '2010-04-02 15:32:29.000000', NULL, 0),
(5927604, 861933, 30214, '<td valign="top">feel very sorry for you Kelly! T\As Raj said, that''s why you need to switch to RAW shooting ASAP. It is very difficult to destroy RAW files, anything you do with them is saved elsewhere.</td>', 'feel very sorry for you Kelly! T\As Raj said, that''s why you need to switch to RAW shooting ASAP. It is very difficult to destroy RAW files, anything you do with them is saved elsewhere.', '2010-04-02 16:01:33.000000', NULL, 0),
